from pathlib import Path
import sys

paths=[Path(p) for p in sys.argv[1:]] or [Path('/tmp/a2-pwa/www/app.html')]
if not paths[0].exists() and not sys.argv[1:]: paths=[Path('www/app.html')]
decode=lambda x:x.replace('§',chr(96)).replace('¤',chr(36))

SUMMARY=decode(r'''function memberPlanForMonth(m,month=currentBillingMonth()){const plans=m?.planByMonth||{};if(Object.prototype.hasOwnProperty.call(plans,month))return planValue(plans[month]);return planValue(m?.planAmount||m?.plan)}
function memberPlanIsSet(m,month){return month<=currentBillingMonth()||Object.prototype.hasOwnProperty.call(m?.planByMonth||{},month)}
function memberSummary(m,month=currentBillingMonth()){const plan=memberPlanForMonth(m,month),paid=memberPaid(m,month),opening=priorClosingBalance(m,month),available=opening+paid,due=Math.max(0,plan-available),advance=Math.max(0,available-plan),status=advance>0.005?'ADVANCE':due<=0.005?'PAID':available>0.005?'PARTIAL':'DUE';return{plan,paid,opening,carryForward:opening,available,due,advance,status,month}}''')

MEMBERS=decode(r'''function members(){const v=window._memberView||{},term=String(v.q||'').toLowerCase(),rows=state.data.members.filter(m=>!term||[m.name,m.phone,m.plan].some(y=>String(y||'').toLowerCase().includes(term)));return§<div class=top style="margin-top:14px"><div><p class=muted style="margin:0">¤{state.data.members.length} Members</p><div class=small>Member details and current plan</div></div>¤{state.profile.role==='admin'?'<button class=btn onclick=memberForm()>+ Add</button>':''}</div><div class=ref-toolbar><input class=ref-search placeholder="Search members…" value="¤{esc(v.q||'')}" oninput="setMemberView('q',this.value)"></div><div class="card list">¤{rows.map(m=>§<div class=row><span><b>¤{esc(m.name)}</b><small class=muted> · ¤{esc(m.phone||'No phone')}</small></span><span>Current Plan<br><b>AED ¤{money(memberPlanForMonth(m,currentBillingMonth()))}</b></span><span></span><span>¤{state.profile.role==='admin'?§<div class=actions><button class=ghost onclick="memberFormById('¤{m.id}')">Edit</button><button class="ghost danger" onclick="delRecord('members','¤{m.id}','member')">Delete</button></div>§:''}</span></div>§).join('')||'<p class=muted>No members match this search.</p>'}</div>§}''')

HELPERS=decode(r'''
window.openMonthPlan=(memberId,month)=>{if(state.profile?.role!=='admin')return toast('Admin only');const m=state.data.members.find(x=>String(x.id)===String(memberId));if(!m)return toast('Member not found');const selected=memberPlanForMonth(m,month)||200;modal(§<div class=top><div><h3 style="margin:0">Set Monthly Plan</h3><div class=small>¤{esc(m.name)} · ¤{month}</div></div><button type=button class=ghost onclick=closeM()>✕</button></div><div style="margin-top:16px"><label>Select plan first</label><input id=monthPlanValue type=hidden value="¤{selected}"><div class=plan-choice style="margin-top:8px">¤{[100,200,250].map(v=>§<button type=button class="ghost plan-option ¤{selected===v?'selected':''}" onclick="selectMonthPlan(¤{v},this)">AED ¤{v}</button>§).join('')}</div><div id=monthPlanDetails class=note style="margin-top:14px">Selected plan: <b>AED ¤{selected}</b><br>After saving, payment, carry-forward and WhatsApp options will appear for this month.</div><button id=monthPlanSaveBtn type=button class=btn style="width:100%;margin-top:14px" onclick="saveMonthPlan('¤{m.id}','¤{month}')">ADD PLAN</button></div>§)};
window.selectMonthPlan=(value,button)=>{const amount=Number(value);if(![100,200,250].includes(amount))return;¤('monthPlanValue').value=amount;document.querySelectorAll('.plan-option').forEach(x=>x.classList.toggle('selected',x===button));const box=¤('monthPlanDetails');if(box)box.innerHTML='Selected plan: <b>AED '+amount+'</b><br>After saving, payment, carry-forward and WhatsApp options will appear for this month.'};
window.saveMonthPlan=async(memberId,month)=>{const btn=¤('monthPlanSaveBtn'),amount=Number(¤('monthPlanValue')?.value);if(![100,200,250].includes(amount))return toast('Select AED 100, AED 200 or AED 250');try{if(btn){btn.disabled=true;btn.textContent='SAVING…'}await updateDoc(doc(db,'members',memberId),{['planByMonth.'+month]:amount,updatedAt:serverTimestamp()});closeM();toast(month+' plan saved · AED '+amount)}catch(e){err(e)}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent='ADD PLAN'}}};
''')

PAYMENTS=decode(r'''function payments(){const month=window._paymentMonth||currentBillingMonth(),isMember=state.profile.role==='member',self=isMember?linkedMember(auth.currentUser.uid):null,history=(isMember?state.data.payments.filter(x=>String(x.uid||'')===String(auth.currentUser.uid)):state.data.payments).filter(x=>paymentMonth(x)===month).sort((a,b)=>paymentSortTime(b)-paymentSortTime(a)),monthNav=§<div class=ref-month><button class=ghost onclick="movePaymentMonth(-1)">‹</button><b>¤{month}</b><button class=ghost onclick="movePaymentMonth(1)">›</button></div>§;if(isMember){if(self&&!memberPlanIsSet(self,month))return§¤{monthNav}<div class=card style="margin-top:12px"><h3>Plan not added</h3><p class=muted>The admin has not selected your plan for ¤{month} yet.</p></div>§;const q=self?memberSummary(self,month):{plan:0,paid:0,opening:0,due:0,advance:0,status:'DUE'};return§¤{monthNav}<div class=grid>¤{metric('Plan','AED '+money(q.plan))}¤{metric('Paid This Month','AED '+money(q.paid))}¤{metric('Carry Forward',(q.opening>=0?'+ ':'− ')+'AED '+money(Math.abs(q.opening)))}¤{metric(q.advance>0?'Advance':'Due','AED '+money(q.advance>0?q.advance:q.due))}¤{metric('Status',q.status)}</div><div class=card style="margin-top:12px"><h3>Payment History</h3><div class=list>¤{history.length?history.map(x=>§<div class=row><span><b>¤{paymentDateLabel(x)}</b><small class=muted> · ¤{esc(x.name||self?.name||'Member')}</small></span><span>AED ¤{money(paidValue(x))}<br><small class=muted>¤{cashCardMethod(x,'payment')}</small></span><span>¤{esc(x.status||'Recorded')}</span><span></span></div>§).join(''):'<p class=muted>No payment recorded for this month yet.</p>'}</div></div>§}const summaries=state.data.members.map(m=>({m,q:memberSummary(m,month),ready:memberPlanIsSet(m,month)}));return§¤{monthNav}<div class=top style="margin-top:14px"><div><p class=muted style="margin:0">Payments · ¤{month}</p><div class=small>For a future month, set each member plan first.</div></div>¤{month<=currentBillingMonth()?§<button class=btn onclick="paymentForm({billingMonth:'¤{month}'})">+ Payment / Advance</button>§:''}</div><div class=card style="margin-top:12px"><h3>Member Balances</h3><div class=list>¤{summaries.map(({m,q,ready})=>ready?§<div class=row><span><b>¤{esc(m.name)}</b><small class=muted> · Plan AED ¤{money(q.plan)}</small></span><span>Paid AED ¤{money(q.paid)}<br><small class=muted>Carry ¤{q.opening>=0?'+':'−'} AED ¤{money(Math.abs(q.opening))}</small><br><small class=muted>¤{q.advance>0?'Advance AED '+money(q.advance):'Due AED '+money(q.due)}</small></span><span class="tag ¤{q.status==='DUE'?'due':q.status==='PARTIAL'?'partial':'paid'}">¤{q.status}</span><span><div class=actions><button class=ghost onclick="paymentForm({uid:'¤{memberKey(m)}',billingMonth:'¤{month}'})">Add Payment</button><button class=ghost onclick="openCarryAdjustment('¤{m.id}','¤{month}')">Carry Forward</button><button class=ghost onclick="waDue('¤{esc(m.phone||'')}','¤{esc(m.name||'Member')}','¤{month}',¤{q.plan},¤{q.paid},¤{q.opening},¤{q.due},¤{q.advance})">WhatsApp</button>¤{month>currentBillingMonth()?§<button class=ghost onclick="openMonthPlan('¤{m.id}','¤{month}')">Edit Plan</button>§:''}</div></span></div>§:§<div class=row><span><b>¤{esc(m.name)}</b><small class=muted> · ¤{month}</small></span><span><span class=tag>PLAN REQUIRED</span></span><span></span><span><button class=btn onclick="openMonthPlan('¤{m.id}','¤{month}')">+ Add Plan</button></span></div>§).join('')}</div></div><div class=card style="margin-top:12px"><h3>¤{month} Payment History · Newest First</h3><div class=list>¤{history.length?history.map(x=>{const m=linkedMember(x.uid);return§<div class=row><span><b>¤{paymentDateLabel(x)}</b><small class=muted> · ¤{esc(x.name||m?.name||'Member')}</small></span><span>AED ¤{money(paidValue(x))}<br><small class=muted>¤{cashCardMethod(x,'payment')}</small></span><span>¤{esc(x.status||'Recorded')}</span><span><div class=actions><button class=ghost onclick="paymentFormById('¤{x.id}')">Edit</button><button class="ghost danger" onclick="deletePayment('¤{x.id}')">Delete</button></div></span></div>§}).join(''):'<p class=muted>No payments recorded for this month.</p>'}</div></div>§}''')

def between(s,a,b,r):
    i=s.find(a); j=s.find(b,i)
    if i<0 or j<0: raise SystemExit(f'Markers missing: {a} / {b}')
    return s[:i]+r+s[j:]

for app in paths:
    s=app.read_text()
    s=between(s,'function memberSummary(', '\nfunction currentMonthExpenses(',SUMMARY)
    s=between(s,'function members(){','\nwindow.memberForm=',MEMBERS)
    s=between(s,'function payments(){','\nwindow.paymentFormForMember=',HELPERS+'\n'+PAYMENTS)
    s=s.replace('base=planValue(m.planAmount||m.plan)/200','base=memberPlanForMonth(m,month)/200')
    s=s.replace('planValue(m.planAmount||m.plan)>0','memberPlanForMonth(m,month)>0')
    s=s.replace('baseWeight=planValue(m.planAmount||m.plan)/200','baseWeight=memberPlanForMonth(m,month)/200')
    s=s.replace('plan:planValue(m.planAmount||m.plan),baseWeight','plan:memberPlanForMonth(m,month),baseWeight')
    s=s.replace("plan=planValue(m?.planAmount||m?.plan||x.planAmount||200)","plan=memberPlanForMonth(m,billingMonth)||planValue(x.planAmount||200)")
    need=['planByMonth','memberPlanIsSet','openMonthPlan','PLAN REQUIRED','+ Add Plan','For a future month, set each member plan first.','Member details and current plan']
    missing=[x for x in need if x not in s]
    if missing: raise SystemExit('Month plan flow missing: '+', '.join(missing))
    app.write_text(s)
    print('Added month-specific plan setup flow:',app)
